const yutCharge={active:false,mode:null,pointer:null,key:null,scope:'',started:0,frame:null,suppressUntil:0};
const yutChargeNow=()=>typeof performance!=='undefined'&&typeof performance.now==='function'?performance.now():Date.now();
const yutChargePower=elapsed=>{const phase=(Math.max(0,elapsed)%2800)/1400;return Math.max(0,Math.min(100,(phase<=1?phase:2-phase)*100));};
function yutThrowScope(){const g=state?.game;return [state?.code,g?.id,g?.turn,g?.turnDeadline].join(':');}
function canChargeYut(){const g=state?.game;return !!(state&&(state.gameType||'yut')==='yut'&&g?.status==='playing'&&!isSpectator&&Number.isInteger(seat)&&g.turn===seat&&g.rollCredits>0&&socket.connected&&!animating&&!movePending&&Number(g.turnDeadline)>Date.now());}
function setYutChargePower(power){
 const value=Math.max(0,Math.min(100,Number(power)||0)),rounded=Math.round(value),gauge=$('throw-gauge');$('throw-power').value=String(value);
 if($('power-label').textContent!==rounded+'%')$('power-label').textContent=rounded+'%';
 if(gauge){gauge.setAttribute('aria-valuenow',String(rounded));gauge.setAttribute('aria-valuetext','윷 던지기 세기 '+rounded+'퍼센트');gauge.classList.toggle('danger',value<10||value>90);gauge.querySelector('.throw-gauge-fill').style.transform=`scaleX(${value/100})`;}
}
function stopYutCharge(reset=true){
 const pointer=yutCharge.pointer;yutCharge.active=false;yutCharge.mode=null;yutCharge.pointer=null;yutCharge.key=null;
 if(yutCharge.frame!==null){if(typeof cancelAnimationFrame==='function')cancelAnimationFrame(yutCharge.frame);else document.defaultView?.cancelAnimationFrame(yutCharge.frame);yutCharge.frame=null;}
 $('throw').setAttribute('aria-pressed','false');$('throw-gauge')?.classList.remove('charging');
 if(pointer!==null){try{if($('throw').hasPointerCapture?.(pointer))$('throw').releasePointerCapture(pointer);}catch{}}
 if(reset)setYutChargePower(0);
 const g=state?.game;if(g?.rollCredits>0)$('throw').textContent='꾹 눌렀다 떼어 던지기';
}
function cancelYutCharge(){if(!yutCharge.active)return;stopYutCharge();}
function yutChargeFrame(){
 if(!yutCharge.active)return;
 if(!canChargeYut()||yutCharge.scope!==yutThrowScope()||document.hidden){cancelYutCharge();return;}
 setYutChargePower(yutChargePower(yutChargeNow()-yutCharge.started));
 yutCharge.frame=typeof requestAnimationFrame==='function'?requestAnimationFrame(yutChargeFrame):document.defaultView.requestAnimationFrame(yutChargeFrame);
}
function startYutCharge(mode,pointer=null,key=null){
 if(yutCharge.active||!canChargeYut())return false;
 Object.assign(yutCharge,{active:true,mode,pointer,key,scope:yutThrowScope(),started:yutChargeNow()});
 $('throw').setAttribute('aria-pressed','true');$('throw').textContent='원하는 세기에서 놓으세요';$('throw-gauge').classList.add('charging');setYutChargePower(0);yutChargeFrame();return true;
}
function releaseYutCharge(){
 if(!yutCharge.active)return;
 const allowed=canChargeYut()&&yutCharge.scope===yutThrowScope()&&!document.hidden,power=Math.round(yutChargePower(yutChargeNow()-yutCharge.started));
 yutCharge.suppressUntil=yutChargeNow()+800;stopYutCharge(!allowed);if(!allowed)return;setYutChargePower(power);void submitYutThrow(power);
}
