// Resume requests have their own retry path: a timeout must never erase a seat token.
let resumeGeneration=0,resumeTimer=null,resumeMissingRoom=false;
function stopResume(){resumeGeneration++;clearTimeout(resumeTimer);resumeTimer=null;}
function resumeRoom(code,stored){
 stopResume();const generation=resumeGeneration;let attempts=0;
 const attempt=()=>{
  if(generation!==resumeGeneration||!socket.connected||localStorage.getItem(`field-yut:session:${code}`)!==stored)return;
  socket.timeout(8000).emit('room:join',{code,token:stored},(err,res)=>{
   if(generation!==resumeGeneration||!socket.connected)return;
   resumeMissingRoom=!err&&res?.code==='ROOM_NOT_FOUND';
   if(!err&&res?.ok){saveSession(res.code,res.token,res.seat,res.role||'player');showConnectionVersion(BUILD_VERSION);return;}
   attempts++;$('connection').textContent='● 방 재연결 중 · 참가 정보 유지';$('connection').classList.add('off');
   if(attempts===1)notify('방에 다시 연결하고 있습니다. 참가 정보는 유지됩니다.');
   resumeTimer=setTimeout(attempt,Math.min(10000,1000*2**Math.min(attempts-1,4)));
  });
 };attempt();
}
