function formatKoreanMoney(value){const number=Number(value||0);if(!Number.isFinite(number))return '0';let n=Math.trunc(Math.abs(number));const parts=[];for(const [unit,size] of [['조',1000000000000],['억',100000000],['만',10000]]){const count=Math.floor(n/size);if(count){parts.push(count.toLocaleString('ko-KR')+unit);n-=count*size;}}if(n||!parts.length)parts.push(n.toLocaleString('ko-KR'));return (number<0?'−':'')+parts.join(' ');}
const chip=formatKoreanMoney;
function updateMoneyInputHints(){for(const id of ['badugi-base','badugi-chips','seotda-base','seotda-chips','poker-base','poker-chips']){const input=document.getElementById(id),output=document.getElementById(id+'-formatted');if(input&&output)output.textContent=formatKoreanMoney(input.value)+' 칩';}}
for(const id of ['badugi-base','badugi-chips','seotda-base','seotda-chips','poker-base','poker-chips'])document.getElementById(id)?.addEventListener('input',updateMoneyInputHints);updateMoneyInputHints();

