async function sendBadugi(data){if(badugiBusy||!state?.badugi||isSpectator)return;const revision=state.badugi.revision;badugiBusy=true;renderBadugi();try{await action('badugi:act',{...data,revision});}finally{badugiBusy=false;if(state?.gameType==='badugi')renderBadugi();}}
for(const type of ['yut','badugi','gomoku','seotda','poker','alkkagi','kkung','sichuan'])$('tab-'+type).addEventListener('click',()=>{if(state){notify('현재 방에서 나간 뒤 다른 게임을 선택해 주세요.');return;}if(createBusy)return;chosenGame=type;lobbyFilter=type;lobbyPage=1;localStorage.setItem('hodon:last-game',type);render();});
// Badugi's action clock is updated centrally.
// Included in app.js; no client-side rule adjudication or opponent control.
let gomokuBusy=false;
const gomTime=n=>{const t=Math.ceil(Math.max(0,n)/1000);return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');};
function gomokuHint(g,s){
 if(!g)return '두 명이 입장하면 방장이 대국을 시작할 수 있습니다.';
 if(g.status==='finished')return (g.winner===null?'무승부 · '+g.reason:`${s.players[g.winner]?.name||'대국자'} 승리 · ${g.reason}`)+(g.winner!==null&&s.gomokuSamePlayers!==false?(g.nextBlack===null?' · 승자가 다음 대국의 흑백을 선택해 주세요.':` · 다음 흑: ${s.players[g.nextBlack]?.name}`):'');
 if(g.pending)return `${s.players[g.pending.from]?.name} 님이 ${g.pending.kind==='undo'?'무르기':'무승부'}를 요청했습니다.`;
 const who=s.players[g.turn]?.name||'대국자';
 return `${who} 님 · ${g.colors[g.turn]===1?'흑돌':'백돌'} 차례${g.history.length===0?' · 빈 교차점 어디에나 착수하세요.':''}`;
}
function gomokuBowl(color){const id='gom-bowl-'+color,white=color==='white',points=[[27,50],[44,45],[62,52],[38,62],[58,66],[75,60],[51,33],[70,38],[25,65]];return `<svg class="gom-bowl ${color}" viewBox="0 0 100 100" aria-hidden="true"><defs><radialGradient id="${id}-wood" cx=".35" cy=".2"><stop stop-color="#94633c"/><stop offset=".55" stop-color="#4d2f1b"/><stop offset="1" stop-color="#21170f"/></radialGradient><radialGradient id="${id}-stone" cx=".3" cy=".25"><stop stop-color="${white?'#fffef7':'#8e908c'}"/><stop offset=".4" stop-color="${white?'#f8f4e6':'#2f3331'}"/><stop offset="1" stop-color="${white?'#afa58c':'#060807'}"/></radialGradient></defs><ellipse cx="50" cy="64" rx="45" ry="29" fill="url(#${id}-wood)"/><ellipse cx="50" cy="50" rx="46" ry="32" fill="url(#${id}-wood)" stroke="#ae8054" stroke-width="2"/><ellipse cx="50" cy="49" rx="39" ry="25" fill="#19110a"/>${points.map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="10" ry="8.5" fill="url(#${id}-stone)" stroke="${white?'#8a806c':'#090a08'}" stroke-width=".5"/>`).join('')}<path d="M9 57Q50 91 91 57" fill="none" stroke="#805431" stroke-width="4"/></svg>`;}
function gomokuSvg(g,s){
 const b=g?.board||Array(225).fill(0),unit=510/14,point=i=>[45+(i%15)*unit,45+Math.floor(i/15)*unit];
 const own=!isSpectator&&Number.isInteger(seat),active=own&&g?.status==='playing'&&g.turn===seat&&!g.pending&&!gomokuBusy;
 const forbidden=new Map((g?.forbidden||[]).map(p=>[p.i,p.reason]));
 let html=`<svg id="gomoku-board" viewBox="0 0 600 610" role="group" aria-label="15 곱하기 15 국제 렌주 오목판"><defs><linearGradient id="gom-wood" x2=".7" y2="1"><stop stop-color="#f5d093"/><stop offset=".42" stop-color="#e9ba73"/><stop offset="1" stop-color="#c58f48"/></linearGradient><radialGradient id="gom-black" cx=".3" cy=".2"><stop stop-color="#b4b5ab"/><stop offset=".16" stop-color="#686b65"/><stop offset=".44" stop-color="#292b29"/><stop offset=".85" stop-color="#0c0d0c"/><stop offset="1" stop-color="#020302"/></radialGradient><radialGradient id="gom-white" cx=".3" cy=".2"><stop stop-color="#fffefa"/><stop offset=".4" stop-color="#fffdf6"/><stop offset=".8" stop-color="#e5dfcc"/><stop offset="1" stop-color="#a89e84"/></radialGradient><pattern id="gom-grain" width="42" height="11" patternUnits="userSpaceOnUse"><path d="M0 3Q20 0 42 4M0 9Q20 6 42 10" fill="none" stroke="#89551a" stroke-opacity=".06"/></pattern></defs><rect x="5" y="16" width="590" height="592" rx="10" fill="#83552c" stroke="#4c2c17" stroke-width="3"/><path d="M15 602H585" stroke="#c38e48" stroke-width="2"/><rect x="5" y="5" width="590" height="585" rx="8" fill="url(#gom-wood)" stroke="#925d28" stroke-width="5"/><rect x="10" y="10" width="580" height="583" rx="10" fill="url(#gom-grain)" stroke="#fbe2a1" stroke-width="2"/>`;
 for(let n=0;n<15;n++){const v=45+n*unit;html+=`<path d="M45 ${v}H555 M${v} 45V555" stroke="#51330f" stroke-width="1.1"/><text x="${v}" y="29" text-anchor="middle">${String.fromCharCode(65+n)}</text><text x="${v}" y="581" text-anchor="middle">${String.fromCharCode(65+n)}</text><text x="25" y="${v+4}" text-anchor="middle">${15-n}</text><text x="576" y="${v+4}" text-anchor="middle">${15-n}</text>`;}
 for(const [x,y] of [[3,3],[11,3],[7,7],[3,11],[11,11]])html+=`<circle cx="${45+x*unit}" cy="${45+y*unit}" r="3.4" fill="#51330f"/>`;
 b.forEach((color,i)=>{if(!color)return;const [x,y]=point(i);html+=`<circle class="gom-stone" data-stone="${i}" cx="${x}" cy="${y}" r="15.6" fill="url(#gom-${color===1?'black':'white'})" stroke="${color===1?'#000':'#b6aa8f'}" stroke-width="1"/>`;if(g.winLine.includes(i))html+=`<circle cx="${x}" cy="${y}" r="17.8" fill="none" stroke="#ffed70" stroke-width="3"/>`;});
 const last=g?.history.at(-1);if(last){const [x,y]=point(last.i);html+=`<circle cx="${x}" cy="${y}" r="4" fill="${last.color===1?'#ffe58b':'#af371f'}" pointer-events="none"/>`;}
 for(const [i,reason] of forbidden){const [x,y]=point(i);html+=`<path d="M${x-5} ${y-5}l10 10m0-10l-10 10" stroke="#b92624" stroke-width="1.7"><title>${reason} 금수</title></path>`;}
 g?.proposals.forEach((i,n)=>{const [x,y]=point(i);html+=`<circle cx="${x}" cy="${y}" r="15" fill="#f9e8ab" stroke="#a47516" stroke-width="2"/><text x="${x}" y="${y+5}" text-anchor="middle" font-weight="900">${n+1}</text>`;});
 for(let i=0;i<225;i++){
  if(b[i])continue;const [x,y]=point(i),row=Math.floor(i/15),col=i%15;
  let legal=active&&!forbidden.has(i);
  html+=`<rect data-intersection="${i}" x="${x-unit/2}" y="${y-unit/2}" width="${unit}" height="${unit}" fill="transparent" ${legal?'class="gom-hit" role="button" tabindex="0"':'class="gom-inactive" aria-disabled="true"'} aria-label="${String.fromCharCode(65+col)}${15-row}${forbidden.has(i)?' '+forbidden.get(i)+' 금수':''}"><title>${String.fromCharCode(65+col)}${15-row}${forbidden.has(i)?' · '+forbidden.get(i)+' 금수':''}</title></rect>`;
 }
 return html+'<text x="300" y="601" text-anchor="middle" font-size="10" font-weight="900">FIELD × HODON</text></svg>';
}
function renderGomokuBase(){
 ui.landing.classList.add('hidden');ui.room.classList.add('hidden');$('badugi-section').classList.add('hidden');const root=$('gomoku-section');root.classList.remove('hidden');
 const s=state,g=s.gomoku,pending=g?.status==='playing',own=!isSpectator&&Number.isInteger(seat),mine=own&&g?.turn===seat;
 if(socket.connected)showConnectionVersion(s.serverVersion);
 const hint=gomokuHint(g,s),colorName=g?.status==='finished'?'대국 종료':g?.phase==='play'?(g.colors[g.turn]===1?'흑돌 차례':'백돌 차례'):'오프닝 진행';
 root.innerHTML=`<div class="gom-layout"><section class="gom-main"><div class="gom-title"><h1>❧ 호돈의 오목 대결 ❧</h1><span>${g?colorName:'입장 대기'}</span></div><div class="gom-hint" role="status">${safe(hint)}</div>
 ${own&&g?.status==='finished'&&g.winner===seat&&g.nextBlack===null&&s.gomokuSamePlayers!==false?'<div class="gom-choice"><button data-color="1">● 다음 경기 흑 선택</button><button data-color="2">○ 다음 경기 백 선택</button></div>':''}
 ${g?.pending&&own&&g.pending.from!==seat?'<div class="gom-choice"><button id="gom-accept">요청 수락</button><button id="gom-decline">거절</button></div>':''}
 <div class="gom-board-shell">${gomokuSvg(g,s)}${gomokuBowl('white')}${gomokuBowl('black')}</div>
 <div class="gom-duel">${s.players.map((p,i)=>`<div class="${pending&&g.turn===i?'active':''}">${avatarHtml(p)}<strong>${safe(p?.name||'입장 대기')}</strong><span class="gom-color ${g?.colors[i]===2?'white':'black'}"></span><b class="gom-clock" data-clock="${i}">${gomTime(g?.clocks[i]??s.gomokuMinutes*60000)}</b></div>${i===0?'<em>VS</em>':''}`).join('')}</div>
 <div class="gom-buttons"><button id="gom-undo" ${!pending||!own||g.phase!=='play'||g.pending||gomokuBusy?'disabled':''}>↶ 무르기 요청</button><button id="gom-resign" ${!pending||!own||gomokuBusy?'disabled':''}>⚑ 기권</button><button id="gom-start" ${pending||!own||seat!==s.host||(g?.status==='finished'&&g.winner!==null&&g.nextBlack===null&&s.gomokuSamePlayers!==false)||!roomReady(s)?'disabled':''}>⟳ ${g?'새 대국':'대국 시작'}</button><button id="gom-rules">▤ 대국 규칙</button></div>
 <div class="gom-minor"><button id="gom-pass" ${!pending||!mine||g.phase!=='play'||g.pending||gomokuBusy?'disabled':''}>한 수 패스</button><button id="gom-draw" ${!pending||!mine||g.phase!=='play'||g.pending||gomokuBusy?'disabled':''}>무승부 제안</button><span>15×15 렌주 · 흑 3·3 / 4·4 / 장목 금수</span></div>
 ${g?.status==='finished'?`<div class="gom-finish">🏆 ${safe(hint)} <button id="gom-result">대국 결과 보기</button></div>`:''}</section>
 <aside class="gom-sidebar"><section class="gom-panel"><h2>ⓘ 방 정보</h2><h3>${safe(s.players[s.host]?.name||'호돈')}의 오목방</h3><p class="gom-roomcode">${safe(s.code)}</p><div class="gom-side-actions"><button id="gom-invite">♟ 초대</button><button id="gom-leave" ${leaveBusy?'disabled':''}>${roomLeaveText()}</button></div></section>
 <section class="gom-panel"><h2>♟ 대국자</h2>${s.players.map((p,i)=>`<div class="gom-person">${avatarHtml(p)}<strong>${safe(p?.name||'입장 대기')}${i===s.host?' ♛':''}</strong><span class="gom-color ${g?.colors[i]===2?'white':'black'}"></span><small>${p&&!p.connected?'재접속 대기':pending?'대국 중':'입장 대기'}</small>${own&&seat===s.host&&p&&i!==seat?`<button class="kick-btn" data-gom-kick="${i}">강퇴</button>`:''}</div>`).join('')}</section>
 <section class="gom-panel"><h2>♟ 대기실 <span>관전자 ${(s.spectators||[]).length}명</span></h2>${(s.spectators||[]).map(w=>`<div class="gom-watcher"><span>${avatarHtml(w)} ${safe(w.name)}</span><small>${w.connected?'관전 중':'오프라인'}</small>${own&&seat===s.host?`<button data-gom-watcher="${safe(w.id)}" class="kick-btn">강퇴</button>`:''}</div>`).join('')||'<p class="gom-muted">아직 관전자가 없습니다.</p>'}</section>
 <section class="gom-panel"><h2>▤ 대국 기록</h2><div class="gom-log">${(g?.log||['친구를 초대해 주세요.']).slice().reverse().map(l=>'<p>'+safe(l)+'</p>').join('')}</div></section>
 <section class="gom-panel"><h2>ⓘ 국제 렌주 안내</h2><p class="gom-rule-summary">흑은 정확한 5목<br/>백은 5목 이상 연결 시 승리</p><details id="gom-rule-detail"><summary>오프닝과 금수 자세히</summary><p>처음부터 각자 배정된 색만 번갈아 둡니다. 첫 경기는 방장이 흑, 첫 흑돌은 빈 교차점 어디에나 놓을 수 있습니다. 경기 종료 후 승자가 다음 경기의 흑 또는 백을 선택하면 두 명이 접속 중일 때 다음 대국이 자동 시작됩니다. 상대가 오프라인이면 재접속을 기다립니다. 무승부면 흑백을 교대합니다. 대국자가 바뀌면 방장이 흑으로 다시 시작합니다.</p><p>흑은 3·3, 4·4, 6목 이상 장목이 금수입니다. 백은 3·3과 4·4가 허용되며 5목 이상이면 승리합니다. 정확한 5목은 우선 승리합니다. 열린 4로 합법적으로 늘릴 수 없는 가짜 3은 3·3에 포함하지 않습니다. 금수는 붉은 ×로 안내하고 착수를 차단합니다.</p><p>온라인 자동 판정과 금수 착수 차단을 적용합니다. 무르기는 상대 동의가 필요한 친선 기능입니다. 요청 중 시계는 멈추고 15초 미응답 시 자동 거절합니다. 국제 대회의 최신 오프닝은 대회마다 다를 수 있으며, 이 방은 렌주 금수와 자체 흑백 교대·승자 선택 방식을 사용하며 RIF 클래식 오프닝을 사용하지 않습니다.</p><p>연속 패스·합의·판 채움은 무승부. 시간 초과·기권은 패배합니다.</p></details></section></aside></div>`;
 root.querySelectorAll('.gom-hit').forEach(el=>{const send=()=>sendGomoku({action:'place',i:Number(el.dataset.intersection)});el.onclick=send;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();send();}};});
 root.querySelectorAll('[data-color]').forEach(el=>el.onclick=()=>sendGomoku({action:'chooseNextColor',color:Number(el.dataset.color)}));
 $('gom-result')&&($('gom-result').onclick=()=>checkGomokuVictory(state.gomoku,true));
 $('gom-start').onclick=()=>action('game:start');$('gom-undo').onclick=()=>sendGomoku({action:'undo'});$('gom-pass').onclick=()=>sendGomoku({action:'pass'});$('gom-draw').onclick=()=>sendGomoku({action:'draw'});
 $('gom-resign').onclick=()=>{if(confirm('기권하시겠습니까? 상대의 승리로 대국이 끝납니다.'))sendGomoku({action:'resign'});};
 $('gom-accept')&&($('gom-accept').onclick=()=>sendGomoku({action:'respond',accept:true}));$('gom-decline')&&($('gom-decline').onclick=()=>sendGomoku({action:'respond',accept:false}));
 $('gom-leave').onclick=requestRoomLeave;$('gom-invite').onclick=async()=>{try{await navigator.clipboard.writeText(`${location.origin}/?room=${s.code}`);notify('초대 링크를 복사했습니다.');}catch{prompt('초대 코드',s.code);}};
 $('gom-rules').onclick=()=>{$('gom-rule-detail').open=true;$('gom-rule-detail').scrollIntoView({block:'center',behavior:'smooth'});};
 root.querySelectorAll('[data-gom-kick]').forEach(b=>b.onclick=async()=>{if(confirm('강퇴하면 상대의 기권 패배로 처리됩니다. 강퇴할까요?'))await action('room:kick',{seat:Number(b.dataset.gomKick)});});
 root.querySelectorAll('[data-gom-watcher]').forEach(b=>b.onclick=async()=>{if(confirm('관전자를 강퇴할까요?'))await action('room:kick',{spectatorId:b.dataset.gomWatcher});});
 root.dataset.clockAt=String(Date.now());checkGomokuVictory(g);
}
function checkGomokuVictory(g,force=false){
 const overlay=$('victory-overlay');
 if(!g||g.status!=='finished'){if(overlay.dataset.gameType==='gomoku')hideVictory();return;}
 const canChoose=!isSpectator&&g.winner===seat&&Number.isInteger(seat)&&g.nextBlack===null&&state.gomokuSamePlayers!==false;
 $('victory-gom-choice').classList.toggle('hidden',!canChoose);
 $('victory-gom-black').disabled=gomokuBusy;$('victory-gom-white').disabled=gomokuBusy;
 if(g.winner!==null&&![0,1].includes(g.winner))return;
 const key=`gomoku:${state.code}:${g.gameNo}`;
 if(!force&&lastWinnerKey===key)return;lastWinnerKey=key;
 setVictoryAvatar(g.avatars?.[g.winner]??state.players[g.winner]?.avatarId);overlay.dataset.gameType='gomoku';$('victory-game').textContent=`호돈 오목 · ${g.gameNo}번째 대국`;
 $('victory-title').textContent=g.winner===null?'무승부':'우승!';
 const name=g.names?.[g.winner]||state.players[g.winner]?.name||'대국자';
 $('victory-name').textContent=g.winner===null?'무승부로 대국 종료':`${name} 우승!`;
 $('victory-members').textContent=g.winner===null?`${g.reason} · 방장이 다음 대국을 시작할 수 있습니다.`:`${g.reason} · 승자가 흑·백을 고르면 다음 대국이 시작됩니다.`;
 openVictoryPopup(g.winner!==null);
}
async function sendGomoku(data){if(gomokuBusy||isSpectator||!state?.gomoku)return;const revision=state.gomoku.revision,gameNo=state.gomoku.gameNo;gomokuBusy=true;renderGomoku();try{await action('gomoku:act',{...data,revision,gameNo});}finally{gomokuBusy=false;if(state?.gameType==='gomoku')renderGomoku();}}
setInterval(()=>{if(state?.gameType!=='gomoku'||!state.gomoku)return;const g=state.gomoku,elapsed=g.status==='playing'&&!g.pending?Date.now()-Number($('gomoku-section').dataset.clockAt||Date.now()):0;document.querySelectorAll('.gom-clock').forEach(el=>{const i=Number(el.dataset.clock);el.textContent=gomTime(g.clocks[i]-(g.turn===i?elapsed:0));});},200);
render();

