 const clock=document.createElement('b');clock.dataset.tableClock=kind;clock.textContent=Math.max(0,Math.ceil((g.deadline-Date.now())/1000))+'초';banner.append(clock);if(kind==='seotda')table.after(banner);else table.before(banner);
